import { IconButton } from "../IconButton";
import { StyleFn } from "..";

export const Dialog: StyleFn = (theme, mode) => {
  const { elevation, color, font, size, responsive } = theme;
  const { root, _ghost } = IconButton(theme, mode);

  return {
    root: {
      position: "relative",
      boxSizing: "border-box",
      display: "flex",
      flexDirection: "column",
      width: "100%",
      maxWidth: "28rem",
      overflowY: "auto",
      borderRadius: "6px",
      color: color.text.neutral.default[mode],
      backgroundColor: color.surface.elevation[6][mode],
      boxShadow: elevation.level6,
      padding: size.spacing[24],
      gap: size.spacing[16],
      textAlign: "left",
      [`@media (max-width:${responsive.breakpoint.xs}px)`]: {
        margin: 0,
        maxWidth: "100%",
        height: "100%",
        maxHeight: "100% !important",
      },
    },
    _scrollContent: {
      display: "flex",
      flexDirection: "column",
      maxHeight: `calc(100% - ${size.spacing[96]})`,
      "& $content": {
        flex: 1,
        overflowY: "auto",
      },
      "& $header, & $actions": {
        flex: "0 0 auto",
      },
    },
    _scrollDialog: {
      flex: "0 1 auto",
      maxHeight: `calc(100% - ${size.spacing[96]})`,
    },
    _scrollBody: {
      margin: `${size.spacing[48]} auto`,
    },
    wrapper: {
      height: "100%",
      outline: 0,
    },
    wrapper_scrollDialog: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
    },
    wrapper_scrollBody: {
      overflowY: "auto",
      overflowX: "hidden",
    },
    wrapper_scrollContent: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
    },
    content: {
      fontSize: font.size.small,
      lineHeight: font.lineheight.small,
      "& p": {
        margin: 0,
      },
      [`@media (max-width:${responsive.breakpoint.xs}px)`]: {
        flexGrow: 1,
      },
    },
    header: {
      fontSize: font.size["heading-6"],
      lineHeight: font.lineheight["heading-6"],
    },
    close: {
      ...root,
      ..._ghost,
      // increase specificity to avoid button override
      // see https://github.airbus.corp/Airbus/design-system/issues/2387
      "&$close": { position: "absolute" },
      top: size.spacing[16],
      right: size.spacing[16],
      lineHeight: size.spacing[8],
    },
    actions: {
      // total space between cotent and action is 32px = paddingTop(16) + gap(16)
      paddingTop: size.spacing[16],
      display: "flex",
      alignItems: "center",
      justifyContent: "flex-end",
      "& > :not(:first-child)": {
        marginLeft: size.spacing[16],
      },
      [`@media (max-width:${responsive.breakpoint.xs}px)`]: {
        flexDirection: "column",
        "& > *": {
          width: "100%",
        },
        "& > :not(:first-child)": {
          marginLeft: 0,
          marginTop: size.spacing[16],
        },
      },
    },
  };
};
